  "Detect Cycle in Linked List": [
    {
      "label": "single node, no cycle",
      "run": "const mk = (arr, c = -1) => { if (!arr.length) return null; const ns = arr.map(v => ({val: v, next: null})); for (let i = 0; i < ns.length - 1; i++) ns[i].next = ns[i + 1]; if (c >= 0) ns[ns.length - 1].next = ns[c]; return ns[0]; };console.log(hasCycle(mk([1])))",
      "output": "false"
    },
    {
      "label": "tail points back to head",
      "run": "const mk = (arr, c = -1) => { if (!arr.length) return null; const ns = arr.map(v => ({val: v, next: null})); for (let i = 0; i < ns.length - 1; i++) ns[i].next = ns[i + 1]; if (c >= 0) ns[ns.length - 1].next = ns[c]; return ns[0]; };console.log(hasCycle(mk([1, 2, 3, 4, 5], 0)))",
      "output": "true"
    },
    {
      "label": "two nodes, no cycle",
      "run": "const mk = (arr, c = -1) => { if (!arr.length) return null; const ns = arr.map(v => ({val: v, next: null})); for (let i = 0; i < ns.length - 1; i++) ns[i].next = ns[i + 1]; if (c >= 0) ns[ns.length - 1].next = ns[c]; return ns[0]; };console.log(hasCycle(mk([1, 2])))",
      "output": "false"
    },
    {
      "label": "tail points to itself in a long list",
      "run": "const mk = (arr, c = -1) => { if (!arr.length) return null; const ns = arr.map(v => ({val: v, next: null})); for (let i = 0; i < ns.length - 1; i++) ns[i].next = ns[i + 1]; if (c >= 0) ns[ns.length - 1].next = ns[c]; return ns[0]; };console.log(hasCycle(mk([1, 2, 3, 4, 5, 6], 5)))",
      "output": "true"
    },
    {
      "label": "duplicate values but no cycle",
      "run": "const mk = (arr, c = -1) => { if (!arr.length) return null; const ns = arr.map(v => ({val: v, next: null})); for (let i = 0; i < ns.length - 1; i++) ns[i].next = ns[i + 1]; if (c >= 0) ns[ns.length - 1].next = ns[c]; return ns[0]; };console.log(hasCycle(mk([7, 7, 7, 7])))",
      "output": "false"
    },
    {
      "label": "10,000 nodes, cycle near the end",
      "run": "const mk = (arr, c = -1) => { if (!arr.length) return null; const ns = arr.map(v => ({val: v, next: null})); for (let i = 0; i < ns.length - 1; i++) ns[i].next = ns[i + 1]; if (c >= 0) ns[ns.length - 1].next = ns[c]; return ns[0]; };const a = Array.from({length: 10000}, (_, i) => i); console.log(hasCycle(mk(a, 9990)))",
      "output": "true"
    }
  ],
