  "Merge Two Sorted Lists": [
    {
      "label": "second list empty",
      "run": "const mk = (a) => { let h = null; for (let i = a.length - 1; i >= 0; i--) h = {val: a[i], next: h}; return h; }; const ta = (h) => { const o = []; while (h) { o.push(h.val); h = h.next; } return o; };console.log(ta(mergeTwoLists(mk([1, 2]), null)))",
      "output": "[1,2]"
    },
    {
      "label": "interleaved [1,3,5] + [2,4,6]",
      "run": "const mk = (a) => { let h = null; for (let i = a.length - 1; i >= 0; i--) h = {val: a[i], next: h}; return h; }; const ta = (h) => { const o = []; while (h) { o.push(h.val); h = h.next; } return o; };console.log(ta(mergeTwoLists(mk([1, 3, 5]), mk([2, 4, 6]))))",
      "output": "[1,2,3,4,5,6]"
    },
    {
      "label": "all equal values",
      "run": "const mk = (a) => { let h = null; for (let i = a.length - 1; i >= 0; i--) h = {val: a[i], next: h}; return h; }; const ta = (h) => { const o = []; while (h) { o.push(h.val); h = h.next; } return o; };console.log(ta(mergeTwoLists(mk([2, 2]), mk([2, 2, 2]))))",
      "output": "[2,2,2,2,2]"
    },
    {
      "label": "negatives and different lengths",
      "run": "const mk = (a) => { let h = null; for (let i = a.length - 1; i >= 0; i--) h = {val: a[i], next: h}; return h; }; const ta = (h) => { const o = []; while (h) { o.push(h.val); h = h.next; } return o; };console.log(ta(mergeTwoLists(mk([-5, 0]), mk([-10, -1, 7, 9]))))",
      "output": "[-10,-5,-1,0,7,9]"
    },
    {
      "label": "second list entirely smaller",
      "run": "const mk = (a) => { let h = null; for (let i = a.length - 1; i >= 0; i--) h = {val: a[i], next: h}; return h; }; const ta = (h) => { const o = []; while (h) { o.push(h.val); h = h.next; } return o; };console.log(ta(mergeTwoLists(mk([10, 20]), mk([1, 2, 3]))))",
      "output": "[1,2,3,10,20]"
    },
    {
      "label": "nodes are reused, not copied",
      "run": "const mk = (a) => { let h = null; for (let i = a.length - 1; i >= 0; i--) h = {val: a[i], next: h}; return h; }; const ta = (h) => { const o = []; while (h) { o.push(h.val); h = h.next; } return o; };const a = mk([1]), b = mk([2]); const r = mergeTwoLists(a, b); console.log(r === a && r.next === b)",
      "output": "true"
    }
  ],
