  "Auto-Retry for Promises": [
    {
      "label": "succeeds first try: called once",
      "run": "let calls=0; const f=autoRetry(async()=>{calls++; return 'ok';}, 3, 5); f().then(v=>console.log(v, calls));",
      "output": "ok 1",
      "waitMs": 300
    },
    {
      "label": "retries=0 means exactly one attempt",
      "run": "let calls=0; const f=autoRetry(async()=>{calls++; throw new Error('x'+calls);}, 0, 5); f().then(()=>console.log('resolved'), e=>console.log(e.message, calls));",
      "output": "x1 1",
      "waitMs": 300
    },
    {
      "label": "rethrows the LAST error, total attempts = retries+1",
      "run": "let calls=0; const f=autoRetry(async()=>{calls++; throw new Error('fail '+calls);}, 2, 5); f().then(()=>console.log('resolved'), e=>console.log(e.message, calls));",
      "output": "fail 3 3",
      "waitMs": 400
    },
    {
      "label": "forwards arguments to fn",
      "run": "let calls=0; const f=autoRetry(async(a,b)=>{calls++; if(calls<2) throw new Error('no'); return a+b;}, 3, 5); f(2,3).then(v=>console.log(v));",
      "output": "5",
      "waitMs": 300
    },
    {
      "label": "succeeds on the final allowed attempt",
      "run": "let calls=0; const f=autoRetry(async()=>{calls++; if(calls<=2) throw new Error('e'); return 'last';}, 2, 5); f().then(v=>console.log(v, calls), e=>console.log('threw', e.message));",
      "output": "last 3",
      "waitMs": 400
    }
  ],
  "Batch Promises by Concurrency": [
    {
      "label": "results keep task order when later tasks finish first",
      "run": "const w=ms=>new Promise(r=>setTimeout(r,ms)); const ts=[40,10,20,5].map((d,i)=>async()=>{await w(d); return i;}); batchPromises(ts,2).then(r=>console.log(r));",
      "output": "[0,1,2,3]",
      "waitMs": 300
    },
    {
      "label": "never exceeds concurrency 2",
      "run": "const w=ms=>new Promise(r=>setTimeout(r,ms)); let now=0,max=0; const ts=Array.from({length:6},(_,i)=>async()=>{now++; max=Math.max(max,now); await w(10); now--; return i;}); batchPromises(ts,2).then(()=>console.log(max));",
      "output": "2",
      "waitMs": 300
    },
    {
      "label": "concurrency 1 runs strictly one at a time",
      "run": "const w=ms=>new Promise(r=>setTimeout(r,ms)); const log=[]; const ts=[1,2,3].map(n=>async()=>{log.push('s'+n); await w(5); log.push('e'+n); return n;}); batchPromises(ts,1).then(r=>console.log(JSON.stringify([r,log])));",
      "output": "[[1,2,3],[\"s1\",\"e1\",\"s2\",\"e2\",\"s3\",\"e3\"]]",
      "waitMs": 300
    },
    {
      "label": "keeps pool full (not chunked): total time well under chunked time",
      "run": "const w=ms=>new Promise(r=>setTimeout(r,ms)); const ts=[60,10,10,10,10].map(d=>async()=>{await w(d); return d;}); const t0=Date.now(); batchPromises(ts,2).then(r=>console.log(JSON.stringify(r), Date.now()-t0 < 100));",
      "output": "[60,10,10,10,10] true",
      "waitMs": 400
    },
    {
      "label": "a rejection rejects the batch",
      "run": "const ts=[async()=>1, async()=>{throw new Error('boom');}, async()=>3]; batchPromises(ts,2).then(r=>console.log('resolved', r), e=>console.log('rejected', e.message));",
      "output": "rejected boom",
      "waitMs": 200
    }
  ],
